text.value:
{
  "css": "/*:host {
  display: block;
  padding: 16px;
}*/

.login-container {
  max-width: 400px;
  margin: 0 auto;
}

.login-button {
  margin-top: 20px;
}

.error-message {
  color: red;
  margin-top: 10px;
}
",
  "typescript": "import { Component, Input } from '@angular/core';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.css']
})
export class LoginComponent {

  /*Begin_c8o_InputDeclaration*/
  @Input() usernameLabel: string = 'Username';
  @Input() passwordLabel: string = 'Password';
  @Input() loginButtonLabel: string = 'Login';
  @Input() errorMessage: string = '';
  /*End_c8o_InputDeclaration*/

  /*Begin_c8o_CompDeclaration*/
  username: string = '';
  password: string = '';
  /*End_c8o_CompDeclaration*/

  constructor() {
    /*Begin_c8o_CompConstructor*/

    /*End_c8o_CompConstructor*/
  }

  /*Begin_c8o_CompFunction*/
  onLoginClick() {
    // Emit event or call a method to handle login externally
    // This component does not call external APIs directly
    console.log('Login clicked with username:', this.username, 'and password:', this.password);
  }
  /*End_c8o_CompFunction*/

}
",
  "XHTML": "<ion-content class="login-container">
  <ion-item>
    <ion-input label="{{this?.usernameLabel}}" [(ngModel)]="this.username" type="text" autocomplete="username"></ion-input>
  </ion-item>
  <ion-item>
    <ion-input label="{{this?.passwordLabel}}" [(ngModel)]="this.password" type="password" autocomplete="current-password"></ion-input>
  </ion-item>
  <ion-button class="login-button" expand="block" (click)="onLoginClick()">{{this?.loginButtonLabel}}</ion-button>
  <ng-container *ngIf="this.errorMessage">
    <div class="error-message">{{this?.errorMessage}}</div>
  </ng-container>
</ion-content>",
  "variables": {
    "usernameLabel": "Username",
    "passwordLabel": "Password",
    "loginButtonLabel": "Login",
    "errorMessage": ""
  },
  "comp-imports": {
    "Component": "@angular/core",
    "Input": "@angular/core"
  },
  "module-imports": {
    "IonicModule": "@ionic/angular",
    "FormsModule": "@angular/forms"
  },
  "module-ngmodules": [
    "IonicModule",
    "FormsModule"
  ],
  "module-ngproviders": [],
  "explanation": "Created a Login component using Ionic v7 components. The component has input properties for labels and error message, and local properties for username and password bound with ngModel. The template uses ion-input with label property and ion-button with click event. The component does not call external APIs but logs login data on button click. CSS styles are scoped and separated."
}
